#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Minimal example for evaluating an individual parcellation

Created for the paper-release repository cleanup.
Author: dzhi
"""
import numpy as np
import pandas as pd
import torch as pt
import Functional_Fusion.atlas_map as am
import FusionModel.evaluate as ev
import HierarchBayesParcel.util as hut

from global_config import DEVICE, EXAMPLE_DIR, RESULTS_DIR

TRAIN_RESULT_DIR = RESULTS_DIR / 'train_individual'
EVAL_RESULT_DIR = RESULTS_DIR / 'evaluation'

# Example files included in the repository or generated by train_individual.py.
SPACE = 'fs32k'
EXAMPLE_NAME = 'example_subject'
TASK_DATA_FILE = EXAMPLE_DIR / 'example_task_contrasts_s4_MSMAll.dscalar.nii'
TASK_INFO_FILE = EXAMPLE_DIR / 'example_task_contrasts.tsv'
INDIV_PROB_FILE = TRAIN_RESULT_DIR / f'{EXAMPLE_NAME}_HBP17_FUSION_indiv_prob.npy'
DIST_FILE = EXAMPLE_DIR / 'distGOD_fs32k.pt'
OUTPUT_FILE = EVAL_RESULT_DIR / f'{EXAMPLE_NAME}_HBP17_FUSION_eval.tsv'

HCP_TASKS = ['EMOTION', 'GAMBLING', 'LANGUAGE', 'MOTOR',
             'RELATIONAL', 'SOCIAL', 'WM']


def load_task_contrasts(atlas, data_file, info_file, positive_only=True):
    info = pd.read_csv(info_file, sep='\t')
    data = atlas.cifti_to_data(str(data_file)).astype(np.float32)
    data = np.nan_to_num(data)
    if positive_only:
        idx = info['positive'].values == 1
        info = info[idx].reset_index(drop=True)
        data = data[idx, :]
    return pt.tensor(data[None, :, :], dtype=pt.get_default_dtype(), device=DEVICE), info


def load_individual_parcellation(file_name):
    if not file_name.exists():
        raise FileNotFoundError(
            f'Could not find {file_name}. Run train_individual.py first.'
        )

    U_indiv = np.load(file_name)
    U_indiv = pt.tensor(U_indiv, dtype=pt.get_default_dtype(), device=DEVICE)
    Pindiv = (pt.argmax(U_indiv, dim=1) + 1).to(pt.get_default_dtype())
    Pindiv = pt.where(Pindiv == 0, pt.nan, Pindiv)
    return Pindiv


def load_surface_distance(file_name):
    if not file_name.exists():
        raise FileNotFoundError(
            f'Could not find {file_name}. Copy the precomputed fs32k surface '
            f'distance tensor distGOD_fs32k.pt into example_data first.'
        )
    return pt.load(file_name, weights_only=True)


def check_eval_shapes(parcels, test_data, dist):
    if parcels.shape[1] != test_data.shape[2]:
        raise ValueError('Parcellation and task data vertex counts differ: '
                         f'{parcels.shape[1]} vs {test_data.shape[2]}.')
    if dist.shape[0] != test_data.shape[2] or dist.shape[1] != test_data.shape[2]:
        raise ValueError('Distance matrix shape does not match task data: '
                         f'{dist.shape} vs {test_data.shape[2]} vertices.')


if __name__ == "__main__":
    EVAL_RESULT_DIR.mkdir(parents=True, exist_ok=True)

    # Step 1: Load atlas and example task-contrast evaluation data.
    atlas, _ = am.get_atlas(SPACE)
    atlas.calculate_symmetry()
    test_data, info = load_task_contrasts(atlas,
                                          TASK_DATA_FILE,
                                          TASK_INFO_FILE,
                                          positive_only=True)

    # Step 2: Load the individual map generated by train_individual.py.
    Pindiv = load_individual_parcellation(INDIV_PROB_FILE)

    # Step 3: Load the precomputed fs32k surface distance matrix.
    # This matches indiv_eval_hcp.py:
    # dist = pt.load(BASE_DIR + '/Atlases/tpl-fs32k/distGOD_fs32k.pt',
    #                weights_only=True)
    dist = load_surface_distance(DIST_FILE)
    check_eval_shapes(Pindiv, test_data, dist)

    # Step 4: Evaluate task inhomogeneity by domain and DCBC on all contrasts.
    rows = []
    info['task_name'] = [s.rstrip('2') for s in info.task_name]
    task_names = HCP_TASKS + ['all']
    for task in task_names:
        if task == 'all':
            idx = [True] * len(info)
        else:
            idx = list(info['task_name'] == task)

        hut.report_cuda_memory()
        inhomo_indiv = ev.calc_test_task_inhomogeneity(Pindiv,
                                                       test_data[:, idx, :],
                                                       return_single=True)
        pt.cuda.empty_cache()
        hut.report_cuda_memory()

        dcbc_value = np.nan
        if task == 'all':
            hut.report_cuda_memory()
            dcbc_indiv = ev.calc_test_dcbc(Pindiv, test_data[:, idx, :], dist,
                                           trim_nan=True)
            pt.cuda.empty_cache()
            hut.report_cuda_memory()
            dcbc_value = pt.where(dcbc_indiv == 0,
                                  pt.nan,
                                  dcbc_indiv).cpu().numpy()[0]

        rows.append({
            'subject_id': EXAMPLE_NAME,
            'task_name': task,
            'num_contrasts': int(np.sum(idx)),
            'dcbc_indiv': dcbc_value,
            'inhomo_indiv': inhomo_indiv.cpu().numpy()[0],
        })

    # Step 5: Save a compact evaluation table.
    results = pd.DataFrame(rows)
    results.to_csv(OUTPUT_FILE, sep='\t', index=False)

    print(results)
    print(f'Saved evaluation table to {OUTPUT_FILE}')
